from pathlib import Path
import subprocess,os,json,platform
p=Path(__file__).resolve().parent;arch=platform.machine();core='52'if arch=='aarch64'else'12';ld=Path('/tmp/xdiff/libdir.txt').read_text().strip()+':'+os.environ.get('LD_LIBRARY_PATH','');e=os.environ.copy();e.pop('LD_LIBRARY_PATH',None);ev='cycles:u'if arch=='aarch64'else'cpu_core/cycles/u';binary=next(x for x in Path('/tmp/xdiff/bins.txt').read_text().splitlines()if'/corebenches-'in x);data=p/('profile-prebuilt.'+arch+'.data');c=['perf','record','-q','-F','1999','-e',ev,'-g','-o',str(data),'--','taskset','-c',core,'env','LD_LIBRARY_PATH='+ld,binary,'--bench','--exact','--test-threads=1','tuple::bench_tuple_comparison'];x=subprocess.run(c,env=e,capture_output=True,text=True,check=True);report=['perf','report','--stdio','--no-children','--percent-limit','0.5','-i',str(data)];y=subprocess.run(report,env=e,capture_output=True,text=True,check=True);(p/('profile-prebuilt.'+arch+'.txt')).write_text(y.stdout+'\n'+y.stderr);sym='__memcmp_avx2_movbe'if arch=='x86_64'else'memcmp';ann=['perf','annotate','--stdio','--symbol',sym,'-i',str(data)];z=subprocess.run(ann,env=e,capture_output=True,text=True);(p/('annotate-memcmp-prebuilt.'+arch+'.txt')).write_text(z.stdout+'\n'+z.stderr);(p/('profile-prebuilt.'+arch+'.json')).write_text(json.dumps(dict(command=c,stdout=x.stdout,stderr=x.stderr,report=report,annotate=ann),indent=2));print(y.stdout)
